:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-row: #0f3460;
  --bg-row-now: #1b2a5e;
  --bg-footer: #16213e;
  --accent-gold: #e2b04a;
  --accent-red: #e05a5a;
  --accent-green: #4abf7e;
  --accent-blue: #4a90e2;
  --text-primary: #f0f0f8;
  --text-secondary: #9090b8;
  --text-meta: #6868a0;
  --border-row: #2a2a5a;
  --tag-now-bg: #e2b04a22;
  --tag-now-text: #e2b04a;
  --tag-open-bg: #4abf7e22;
  --tag-open-text: #4abf7e;
  --tag-full-bg: #e05a5a22;
  --tag-full-text: #e05a5a;
  --btn-bg: #e2b04a;
  --btn-text: #1a1a2e;
  --now-border: #e2b04a;
}

.festival-card {
  width: 520px;
  background: var(--bg-card);
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--border-row);
}

.festival-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  background: var(--bg-header);
  border-bottom: 1px solid var(--border-row);
}

.festival-logo {
  width: 40px;
  height: 40px;
  background: var(--accent-gold);
  color: var(--btn-text);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}

.festival-title {
  flex: 1;
}

.festival-name {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  letter-spacing: 2px;
}

.festival-subtitle {
  font-size: 11px;
  color: var(--text-secondary);
  margin: 2px 0 0;
}

.festival-badge {
  padding: 4px 12px;
  background: var(--accent-gold);
  color: var(--btn-text);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 700;
}

.screenings {
  display: flex;
  flex-direction: column;
}

.screening-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 20px;
  border-bottom: 1px solid var(--border-row);
  transition: background 0.2s;
}

.screening-now {
  background: var(--bg-row-now);
  border-left: 3px solid var(--now-border);
}

.time-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 50px;
}

.time {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.hall {
  font-size: 10px;
  color: var(--text-meta);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.film-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.film-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.film-meta {
  font-size: 11px;
  color: var(--text-secondary);
}

.status-tag {
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.tag-now {
  background: var(--tag-now-bg);
  color: var(--tag-now-text);
}

.tag-open {
  background: var(--tag-open-bg);
  color: var(--tag-open-text);
}

.tag-full {
  background: var(--tag-full-bg);
  color: var(--tag-full-text);
}

.festival-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 20px;
  background: var(--bg-footer);
}

.footer-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-num {
  font-size: 18px;
  font-weight: 800;
  color: var(--accent-gold);
  line-height: 1;
}

.stat-label {
  font-size: 10px;
  color: var(--text-meta);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-divider {
  width: 1px;
  height: 28px;
  background: var(--border-row);
}

.book-btn {
  margin-left: auto;
  padding: 8px 20px;
  background: var(--btn-bg);
  color: var(--btn-text);
  border-radius: 8px;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
}
